insert into public.mn_profiles(id,name,bio,site) values('peterango','Pete Rango','Building new ways to experience music.','');
insert into public.mn_profiles(id,name,bio,site) values('musicnerd','Music Nerd','Little experiments for people who care a lot about music.','https://musicnerd.net');
insert into public.mn_profiles(id,name,bio,site) values('tapeclub','Tape Club','Making room for happy accidents. Loops, textures, and things to get lost in.','');
insert into public.mn_profiles(id,name,bio,site) values('softsignal','Soft Signal','Small tools for big feelings. Exploring the space between color and sound.','');
insert into public.mn_apps(id,creator,name,description,about,url,screenshot,category,kind,status,price,account_required,permissions,embed_mode) values('musicnerd-lens','peterango','Music Nerd Lens','Find the stories behind records, posters, and setlists.','Point your camera at a record, poster, or setlist to explore deep cuts, gear specs, and the stories behind the music. Created by Pete Rango. Camera access is requested by Lens when you start scanning.','https://v0-musicnerd-lens.vercel.app/','/lens-preview.webp','Discover','external','published','Unknown',null,array['camera'],'embedded');
insert into public.mn_apps(id,creator,name,description,about,url,screenshot,category,kind,status,price,account_required,permissions,embed_mode) values('loop-garden','musicnerd','Loop Garden','Build a looping rhythm, one note at a time.','A tiny, playful step sequencer. Tap the pads to plant notes, choose your tempo, and let the pattern loop. No downloads, no right answers. Just a little room to make something.','','/sequencer-preview.webp','Make music','sequencer','published','Free',false,'{}','embedded');
insert into public.mn_apps(id,creator,name,description,about,url,screenshot,category,kind,status,price,account_required,permissions,embed_mode) values('chord-colors','softsignal','Chord Colors','Explore four chords in mellow or bright voicings.','Four colors, four chords. Tap a color to hear it. Switch between mellow and bright voicings and follow your ears.','','/chords-preview.webp','Sound toys','chords','published','Free',false,'{}','embedded');
insert into public.mn_apps(id,creator,name,description,about,url,screenshot,category,kind,status,price,account_required,permissions,embed_mode) values('pocket-tempo','tapeclub','Pocket Tempo','Tap out a tempo and keep your practice in time.','An uncomplicated metronome for practice, ideas, or a quick tempo check. Tap to find your tempo or move the slider, then start the pulse.','','/tempo-preview.webp','Tools','tempo','published','Free',false,'{}','embedded');
